BL = 'Bortse från luftmotståndet.'


def p(*s):
    return ''.join(f'<p>{x}</p>' for x in s)


def kort(ctx, fraga):
    """Delkort med egen text: sammanhang + fråga i eget stycke, fraga = frågan."""
    return {'t': p(ctx, fraga), 'f': fraga}


